#include <stdlib.h>
static struct TreeNode** gen(int l,int r,int*cnt){if(l>r){struct TreeNode**a=malloc(sizeof(*a));a[0]=NULL;*cnt=1;return a;}int cap=16,c=0;struct TreeNode**o=malloc(cap*sizeof(*o));for(int root=l;root<=r;root++){int lc,rc;struct TreeNode**L=gen(l,root-1,&lc),**R=gen(root+1,r,&rc);for(int i=0;i<lc;i++)for(int j=0;j<rc;j++){if(c==cap){cap*=2;o=realloc(o,cap*sizeof(*o));}struct TreeNode*n=malloc(sizeof(*n));n->val=root;n->left=L[i];n->right=R[j];o[c++]=n;}free(L);free(R);}*cnt=c;return o;}struct TreeNode** generateTrees(int n,int*rs){if(!n){*rs=0;return NULL;}return gen(1,n,rs);}
